 const savedState=new Map();if(acceptedCheckout)savedState.set('jadeNative.acceptedGitFirstCheckouts',[folder.uri.toString()]);const context={subscriptions:[],globalState:{get(){},async update(){}},workspaceState:{get:(key,fallback)=>savedState.get(key)??fallback,update:async(key,value)=>{if(stateWriteFailure)throw Error('Private state write failed');savedState.set(key,value);if(changeProjectDuringStateWrite)fs.writeFileSync(projectFile,JSON.stringify({sourceFormat:'jox',workingMode:'source-backed'}));}}};
