 const setup=registerJoxProjectSetup(vscode,context,workspace,{client,configFor,detect:async(...args)=>{calls.push({command:'ui.detect',args});if(detectCancelled)return;const before=selected,prior={...machine},resolved=args[2]?.resolved||{},chosen={};if(!resolved.installPath)chosen.installPath=machine.installPath||detectedInstall;if(!resolved.workingSeedDirectory)chosen.workingSeedDirectory=machine.workingSeedDirectory||detectedSeed;if(args[2]?.deferSave&&privateDetection){const staged=args[2].privateRuntime.stage(chosen);return{settings:chosen,...staged};}if(args[2]?.deferSave)return{settings:chosen,commit:async()=>{Object.assign(machine,chosen);selected=true;},rollback:async()=>{if(runtimeRollbackFailure)throw Error('Runtime rollback failed');for(const key of Object.keys(machine))delete machine[key];Object.assign(machine,prior);selected=before;}};selected=true;return machine;}});
 return{settings:machine,context,vscode,client,configFor,root,folder,sourceFile,projectFile,original,gitMarker,calls,logs,setup,workspace,change:()=>{fs.writeFileSync(sourceFile,'changed saved JOX fixture');snapshotHash='b'.repeat(64);nextSync={passed:true,code:0,report:{noOp:false,loadedFiles:1}};}};
