test('failed explicit profile repair retains the native discovery cause without entering Source setup',async t=>{const f=fixture(t,{configured:true,unknownProfile:true});const result=await f.setup.onboarding.setup(f.folder.uri);assert.match(result.error,/Unknown Jade connection profile/);assert.equal(f.calls.filter(row=>row.command==='working.location').length,0);});

test('successful native profile repair restarts preview against the repaired project fingerprint',async t=>{const f=fixture(t,{configured:true,unknownProfile:true}),request=f.client.request;let repaired=false;f.client.request=function(command,...args){if(command==='cli'){repaired=true;f.calls.push({command,args:args[0]});fs.appendFileSync(f.projectFile,'\n');return{promise:Promise.resolve({passed:true,code:0,created:false,git:{root:f.root,initialized:false,reused:true,ignoreEnsured:true}})};}if(command==='prepare'&&repaired){f.calls.push({command,args:args[0]});return{promise:Promise.resolve({passed:true,code:0,prepared:{config:JSON.parse(fs.readFileSync(f.projectFile,'utf8')),configFile:f.projectFile}})};}return request.call(this,command,...args);};const result=await f.setup.onboarding.setup(f.folder.uri);assert.equal(result.completed,true,JSON.stringify(result));assert.equal(f.calls.filter(row=>row.command==='cli').length,1);assert.equal(f.calls.filter(row=>row.command==='working.initialize').length,1);});

test('staged sync releases reopened inspection and revalidates review after that release',async t=>{const f=fixture(t,{configured:true,existing:true});let releases=0;f.workspace.beforeOperation=async()=>{releases++;if(releases===2)f.settings.installPath='C:/Changed during second inspection release';};const result=await f.setup.onboarding.setup(f.folder.uri);assert.equal(releases,2);assert.equal(result.completed,false);assert.equal(f.calls.filter(row=>row.command==='sync').length,0);});

test('checkout Working preparation waits for a refresh already running on its live previous project',async t=>{const f=fixture(t,{configured:true}),prior=f.workspace.project(f.folder);let finish;const gate=new Promise(resolve=>finish=resolve);f.workspace.changing.set(prior,{promise:gate});const pending=f.setup.onboarding.setup(f.folder.uri);try{await new Promise(resolve=>setImmediate(resolve));assert.equal(f.calls.filter(row=>row.command==='working.initialize').length,0);finish();assert.equal((await pending).completed,true);}finally{finish();await pending;}});

test('review is revalidated after the previous live refresh settles',async t=>{const f=fixture(t,{configured:true}),prior=f.workspace.project(f.folder);let finish;const gate=new Promise(resolve=>finish=resolve);f.workspace.changing.set(prior,{promise:gate});const pending=f.setup.onboarding.setup(f.folder.uri);try{await new Promise(resolve=>setImmediate(resolve));fs.appendFileSync(f.projectFile,'\n');finish();const result=await pending;assert.equal(result.completed,false);assert.equal(f.calls.filter(row=>row.command==='working.initialize').length,0);}finally{finish();await pending;}});

test('provider context refuses Working reopen when the folder closes during final native discovery',async t=>{const f=fixture(t,{configured:true,existing:true}),request=f.client.request;let preparations=0;f.client.request=function(command,...args){const op=request.call(this,command,...args);if(command==='prepare'&&++preparations===4)op.promise=op.promise.then(result=>{f.vscode.workspace.workspaceFolders=[];return result;});return op;};const result=await f.setup.onboarding.setup(f.folder.uri);assert.equal(preparations,4);assert.equal(result.completed,false);assert.equal(f.calls.filter(row=>row.command==='working.prepare').length,0);});
